"해 뜨기 전, 물통을 들고 마을 끝 우물까지 걸었고 물을 가득 채운 돌아오는 길은 늘 더 멀었다":"Trước lúc mặt trời mọc xách thùng nước đi bộ đến giếng cuối làng, và đường về khi thùng đã đầy lúc nào cũng xa hơn",
"해 본 일":"Những nghề đã thử",
"해 질 녘 들길을 따라 마을 끝까지 뛰고 돌아오니, 다리는 후들거려도 마음은 오랜만에 가벼웠다":"Lúc chạng vạng chạy theo đường đồng đến cuối làng rồi quay về, chân run lẩy bẩy mà lòng nhẹ nhõm lâu rồi mới có",
